import java.nio.file.*;import java.sql.*;import java.util.*;
public final class LedgerReconciliationBenchmark{public static void main(String[]a)throws Exception{int samples=Integer.parseInt(a[3]);List<Long>t=new ArrayList<>(samples);try(Connection c=DriverManager.getConnection(a[0],a[1],a[2])){long rows=count(c,"SELECT COUNT(*) FROM aoo_ledger");if(rows<1_000_000)throw new IllegalStateException("ledger capacity failed");String combined=key(c,"EXPLAIN SELECT ledger_id FROM aoo_ledger WHERE entry_status='POSTED' AND channel_code='ROOM' AND created_at>='2026-08-20' AND created_at<'2026-08-21' ORDER BY created_at,ledger_id LIMIT 500"),status=key(c,"EXPLAIN SELECT ledger_id FROM aoo_ledger WHERE entry_status='POSTED' AND created_at>='2026-08-20' AND created_at<'2026-08-21' ORDER BY created_at,ledger_id LIMIT 500"),channel=key(c,"EXPLAIN SELECT ledger_id FROM aoo_ledger WHERE channel_code='ROOM' AND created_at>='2026-08-20' AND created_at<'2026-08-21' ORDER BY created_at,ledger_id LIMIT 500");if(!combined.equals("idx_ledger_reconcile_window")||!status.equals("idx_ledger_status_window")||!channel.equals("idx_ledger_channel_window"))throw new IllegalStateException("ledger plans failed "+combined+"/"+status+"/"+channel);try(PreparedStatement q=c.prepareStatement("SELECT ledger_id FROM aoo_ledger WHERE entry_status=? AND channel_code=? AND created_at>=? AND created_at<? ORDER BY created_at,ledger_id LIMIT 500")){for(int i=0;i<100;i++)query(q);for(int i=0;i<samples;i++){long n=System.nanoTime();query(q);t.add(System.nanoTime()-n);}}Collections.sort(t);double p95=ms(t.get((int)Math.ceil(samples*.95)-1)),p99=ms(t.get((int)Math.ceil(samples*.99)-1));if(p95>30||p99>75)throw new IllegalStateException("ledger latency failed");String j=String.format(Locale.ROOT,"{\n  \"rows\": %d,\n  \"combinedIndex\": \"%s\",\n  \"statusIndex\": \"%s\",\n  \"channelIndex\": \"%s\",\n  \"samples\": %d,\n  \"p95Ms\": %.3f,\n  \"p99Ms\": %.3f,\n  \"mysqlVersion\": \"%s\",\n  \"status\": \"passed\"\n}\n",rows,combined,status,channel,samples,p95,p99,text(c,"SELECT VERSION()"));Files.writeString(Path.of(a[4]),j);System.out.print(j);}}static void query(PreparedStatement q)throws Exception{q.setString(1,"POSTED");q.setString(2,"ROOM");q.setTimestamp(3,Timestamp.valueOf("2026-08-20 00:00:00"));q.setTimestamp(4,Timestamp.valueOf("2026-08-21 00:00:00"));try(ResultSet r=q.executeQuery()){int n=0;while(r.next())n++;if(n==0)throw new SQLException("empty reconciliation window");}}static long count(Connection c,String s)throws Exception{try(Statement q=c.createStatement();ResultSet r=q.executeQuery(s)){r.next();return r.getLong(1);}}static String key(Connection c,String s)throws Exception{try(Statement q=c.createStatement();ResultSet r=q.executeQuery(s)){r.next();return r.getString("key");}}static String text(Connection c,String s)throws Exception{try(Statement q=c.createStatement();ResultSet r=q.executeQuery(s)){r.next();return r.getString(1);}}static double ms(long n){return n/1_000_000d;}}
